{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur le point de savoir si la surface de l'appartement constituait une qualité promise par les venderesses dans le contrat.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Un défaut existe lorsque la chose vendue ne possède pas une qualité promise par le vendeur ou à laquelle l'acheteur pouvait s'attendre selon les règles de la bonne foi.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Cette qualité promise doit être décisive pour l'acheteur.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Pour déterminer si une indication de qualité constitue une promesse, il faut procéder à l'interprétation du contrat.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Les surfaces indiquées dans la plaquette de vente promotionnelle de courtiers ou les plans utilisés lors des pourparlers contractuels constituent des qualités promises que l'acheteur peut en principe considérer comme fiables.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La surface promise d'un appartement est présumée, selon l'expérience générale de la vie, avoir été décisive dans la décision de l'acheteur d'acheter la part d'étage au prix convenu.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que la plaquette de vente permettait d'interpréter le contrat authentique dans le sens que la surface indiquée devait être celle de l'appartement vendu.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le grief des venderesses dans la mesure où il est recevable.",
      "b_propositions": ["P8"]
    }
  ]
}
